import { JxButton, JxDrawer, JxMenu, JxMenuItem, JxMenuSeparator } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface NavDrawerProps {
  onNavigate: (key: NavKey) => void;
}

export default function NavDrawer({ onNavigate }: NavDrawerProps) {
  const [open, setOpen] = useState(false);

  const handleSelect = (key: NavKey) => {
    onNavigate(key);
    setOpen(false);
  };

  return (
    <>
      <JxButton variant="secondary" onClick={() => setOpen(true)}>
        Меню
